r {\n    padding: 60px 0 80px;\n  }\n  .skd-web .converter__desc {\n    margin-top: 16px;\n  }\n}\n\n@media (max-width: 742px) {\n  .skd-web .converter {\n    padding: 40px 0 60px;\n  }\n  .skd-web .converter__list-item:not(:last-child) {\n    margin-bottom: 8px;\n  }\n}\n"]}
